package main

import (
	"os"
	"path/filepath"
	"testing"
)

func TestDeclarationInventorySeesHiddenLocalsAndInterfaces(t *testing.T) {
	root := t.TempDir()
	files := map[string]string{
		"go.mod": "module sample.test/audit\n\ngo 1.23\n",
		"a.go": `package sample
import("encoding/json";"crypto";"net/http")
type Box[T any] struct{ V T }
type Handler struct{}
func (Handler) Accept(payload any) {}
func Source() any {return nil}
func init(){panic("must not execute")}
func hidden(){
 type localAlias = json.RawMessage
 var alias localAlias
 inferred:=Source()
 generic:=Box[any]{}
 callback:=func() any{return nil}
 key:=crypto.PublicKey(nil)
 fault:=recover()
 platform:=http.DefaultClient
 closed:=Box[string]{V:"ok"}
 _=alias;_=inferred;_=generic;_=callback;_=key;_=fault;_=platform;_=closed
}
`,
		"inactive.go": "//go:build inventory_inactive\n\npackage sample\nvar disabled any\n",
		"a_test.go":   "package sample\nvar testsOnly any\n",
	}
	for name, s := range files {
		if err := os.WriteFile(filepath.Join(root, name), []byte(s), 0600); err != nil {
			t.Fatal(err)
		}
	}
	got, err := inspectDeclarations(root)
	if err != nil {
		t.Fatal(err)
	}
	want := map[string]string{"Accept": "function", "payload": "variable", "Source": "function", "localAlias": "local-type", "alias": "variable", "inferred": "variable", "generic": "variable", "callback": "variable", "key": "variable", "fault": "variable"}
	for _, f := range got.Findings {
		if want[f.Name] != f.Kind {
			t.Fatalf("unexpected finding: %+v", f)
		}
		delete(want, f.Name)
		if filepath.Base(f.Position.Filename) != "a.go" || f.Position.Line == 0 {
			t.Fatal("missing source location")
		}
	}
	if got.Packages != 1 || len(got.Findings) != 10 || len(want) != 0 {
		t.Fatalf("incomplete inventory %+v missing %v", got, want)
	}
}
func TestDeclarationInventoryRejectsInvalidBodies(t *testing.T) {
	root := t.TempDir()
	if err := os.WriteFile(filepath.Join(root, "go.mod"), []byte("module sample.test/broken\n\ngo 1.23\n"), 0600); err != nil {
