package main

import (
	"encoding/json"
	"fmt"
	"go/token"
	"go/types"
	"os"
	"sort"
)

type finding struct {
	position token.Position
	name     string
}
type declaration struct {
	Package  string
	Name     string
	Kind     string
	Position token.Position
	Type     string
}
type inventory struct {
	Packages     int
	Declarations int
	Findings     []declaration
}

func inspectDeclarations(root string) (inventory, error) {
	var out inventory
	err := visitCompilerPackages(root, func(pkg *types.Package, fset *token.FileSet, owned map[string]bool, info *types.Info) {
		out.Packages++
		for id, obj := range info.Defs {
			if obj == nil || id.Name == "_" {
				continue
			}
			var kind string
			switch v := obj.(type) {
			case *types.Var:
				if v.IsField() {
					continue
				}
				kind = "variable"
			case *types.TypeName:
				if obj.Parent() == pkg.Scope() {
					continue
				}
				kind = "local-type"
			case *types.Func:
				kind = "function"
			default:
				continue
			}
			out.Declarations++
			if publicOpenPayload(obj.Type(), owned, make(map[types.Type]bool)) {
				out.Findings = append(out.Findings, declaration{pkg.Path(), id.Name, kind, fset.Position(id.Pos()), types.TypeString(obj.Type(), nil)})
			}
		}
	})
	if err != nil {
		return out, err
	}
	sort.Slice(out.Findings, func(i, j int) bool {
		a, b := out.Findings[i], out.Findings[j]
		if a.Position.Filename != b.Position.Filename {
			return a.Position.Filename < b.Position.Filename
		}
		return a.Position.Offset < b.Position.Offset
	})
	return out, nil
}
func main() {
	out, err := inspectDeclarations(os.Args[1])
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(2)
	}

	enc := json.NewEncoder(os.Stdout)
	enc.SetIndent("", "  ")
	if err := enc.Encode(out); err != nil {
		panic(err)
	}
}

